package cn.xiaoyanjiu.ff14chat;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Official offline API only. Account tokens stay in encrypted native storage. */
final class OfficeClient {
 static final String BASE="https://office.youshuomni.com/api/world-chat/v1/";
 static final Map<String,Long> waits=new HashMap<>(),sends=new HashMap<>();
 static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static int number(JSONObject p,String name,int low,int high,int fallback)throws Exception{int n=p.optInt(name,fallback);if(n<low||n>high)throw new IOException("分页参数超出范围");return n;}
 static JSONObject call(Context context,String account,String action,JSONObject p)throws Exception {
  String token=AccountStore.officeToken(context,account);long now=android.os.SystemClock.elapsedRealtime();synchronized(waits){long wait=waits.containsKey(account)?waits.get(account):0;if(now<wait)return failure("RATE_LIMITED","请求过于频繁，请稍后重试",(int)((wait-now+999)/1000));}
  boolean send=action.equals("send");String path;
  if(action.equals("messages"))path="messages?region=cn"+(p.optString("after").isEmpty()?"":"&after_message_id="+enc(p.optString("after")));
  else if(action.equals("posts")){String mode=p.optString("mode","realtime");if(!Arrays.asList("realtime","static","all").contains(mode))throw new IOException("招募类型无效");path="recruitment-posts?region=cn&mode="+mode+"&offset="+number(p,"offset",0,100000,0)+"&limit="+number(p,"limit",1,100,100);if(p.has("category")&&p.optInt("category",-1)>=0)path+="&category="+p.getInt("category");}
  else if(action.equals("detail")){String id=p.optString("post_id");UUID.fromString(id);path="recruitment-posts/"+id+"?region=cn&offset="+number(p,"offset",0,100000,0)+"&limit="+number(p,"limit",1,100,100);}
  else if(send)path="messages";else throw new IOException("不支持的国服接口操作");
  JSONObject body=null;
  if(send){String text=p.optString("text").trim(),id=p.optString("message_id");UUID.fromString(id);int count=text.codePointCount(0,text.length());long mention=p.optLong("mention_alias_id",0);if(count>500||text.codePoints().anyMatch(ch->Character.isISOControl(ch)||ch==0x2028||ch==0x2029)||text.isEmpty()&&mention<=0)throw new IOException("消息应为单行，最多500个Unicode字符；空消息需要有效提及对象");synchronized(waits){long last=sends.containsKey(account)?sends.get(account):0;if(now-last<2000)return failure("RATE_LIMITED","请至少间隔2秒发送",2);sends.put(account,now);}body=new JSONObject().put("region","cn").put("message_id",id).put("text",text);if(mention>0)body.put("mention_alias_id",mention);}
  HttpURLConnection connection=(HttpURLConnection)new URL(BASE+path).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(15000);connection.setRequestProperty("Accept","application/json");
  try{if(send){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Authorization","Bearer "+token);connection.setRequestProperty("X-Request-Id",UUID.randomUUID().toString());connection.setRequestProperty("X-Request-Timestamp",Long.toString(System.currentTimeMillis()/1000));connection.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream output=connection.getOutputStream()){output.write(body.toString().getBytes(StandardCharsets.UTF_8));}}
   int status=connection.getResponseCode();InputStream input=status>=400?connection.getErrorStream():connection.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(input!=null)try(InputStream stream=input){byte[] buffer=new byte[8192];int read;while((read=stream.read(buffer))!=-1){if(bytes.size()+read>2097152)throw new IOException("国服接口响应过大");bytes.write(buffer,0,read);}}JSONObject result;try{result=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));}catch(JSONException e){return failure("HTTP_"+status,"国服服务返回异常（HTTP "+status+"）",0);}result.put("httpStatus",status);if(status>=400){JSONObject error=result.optJSONObject("error");String code=error==null?"HTTP_"+status:error.optString("code","HTTP_"+status);int retry=0;if(status==429||status==503){try{retry=Math.min(3600,Math.max(1,Integer.parseInt(connection.getHeaderField("Retry-After"))));}catch(Exception ignored){retry=5;}synchronized(waits){waits.put(account,android.os.SystemClock.elapsedRealtime()+retry*1000L);}}return failure(code,errorMessage(code),retry).put("httpStatus",status);}return result;
  }finally{connection.disconnect();}
 }
 static String errorMessage(String code){switch(code){case "UNAUTHORIZED":return "接口令牌无效或已重置，请到账号设置更新";case "WORLD_CHAT_MUTED":return "此账号已被禁言";case "SCOPE_DENIED":case "WORLD_CHAT_ACCOUNT_UNAVAILABLE":return "账号或令牌权限不可用";case "RECRUITMENT_NOT_FOUND":return "招募已过期或不存在";case "WORLD_CHAT_MENTION_UNAVAILABLE":return "提及对象不在线或为自己，请重新选择";case "REQUEST_EXPIRED":return "请求时间过期，请校准手机时间";case "WORLD_CHAT_MESSAGE_ID_REUSED":return "消息编号已被使用，请先读取确认";case "WORLD_CHAT_CURSOR_EXPIRED":return "聊天游标过期，正在重新读取";default:return "国服接口请求失败（"+code+"）";}}
 static JSONObject failure(String code,String message,int retry)throws JSONException{return new JSONObject().put("ok",false).put("error",new JSONObject().put("code",code).put("message",message)).put("retryAfter",retry);}
}
